package dao;
import java.sql.*; import java.util.*; import model.Dependente;
public class DependenteDAO {
 public boolean inserir(Dependente d){String q="INSERT INTO dependente(nome,data_nascimento,sexo,alergias,responsavel_id) VALUES(?,?,?,?,?)";try(Connection c=Conexao.conectar();PreparedStatement s=c.prepareStatement(q)){s.setString(1,d.getNome());s.setDate(2,d.getDataNascimento());s.setString(3,d.getSexo());s.setString(4,d.getAlergias());s.setInt(5,d.getResponsavelId());return s.executeUpdate()>0;}catch(Exception e){System.out.println("Erro ao inserir dependente: "+e.getMessage());return false;}}
 public boolean atualizar(Dependente d){String q="UPDATE dependente SET nome=?,data_nascimento=?,sexo=?,alergias=?,responsavel_id=? WHERE id=?";try(Connection c=Conexao.conectar();PreparedStatement s=c.prepareStatement(q)){s.setString(1,d.getNome());s.setDate(2,d.getDataNascimento());s.setString(3,d.getSexo());s.setString(4,d.getAlergias());s.setInt(5,d.getResponsavelId());s.setInt(6,d.getId());return s.executeUpdate()>0;}catch(Exception e){System.out.println("Erro ao atualizar dependente: "+e.getMessage());return false;}}
 public boolean excluir(int id){try(Connection c=Conexao.conectar();PreparedStatement s=c.prepareStatement("DELETE FROM dependente WHERE id=?")){s.setInt(1,id);return s.executeUpdate()>0;}catch(Exception e){System.out.println("Erro ao excluir dependente: "+e.getMessage());return false;}}
 public List<Dependente> listarTodos(){List<Dependente> l=new ArrayList<>();String q="SELECT d.id,d.nome,d.data_nascimento,d.sexo,d.alergias,d.responsavel_id,r.nome nome_responsavel FROM dependente d JOIN responsavel r ON r.id=d.responsavel_id ORDER BY d.nome";try(Connection c=Conexao.conectar();PreparedStatement s=c.prepareStatement(q);ResultSet rs=s.executeQuery()){while(rs.next()){Dependente d=new Dependente();d.setId(rs.getInt("id"));d.setNome(rs.getString("nome"));d.setDataNascimento(rs.getDate("data_nascimento"));d.setSexo(rs.getString("sexo"));d.setAlergias(rs.getString("alergias"));d.setResponsavelId(rs.getInt("responsavel_id"));d.setNomeResponsavel(rs.getString("nome_responsavel"));l.add(d);}}catch(Exception e){System.out.println("Erro ao listar dependentes: "+e.getMessage());}return l;}
}